ALIASES = {'decision tree': 'decision tree classifier', 'dt': 'decision tree classifier', 'logistic': 'logistic regression', 'linear': 'linear regression', 'support vector machine': 'svm', 'k nearest neighbors': 'knn', 'k nearest neighbour': 'knn', 'kmeans': 'k-means', 'k means': 'k-means'}

def gc(model_name):
    """Get a generic practical template by model name."""
    key = " ".join(model_name.lower().strip().split())
    key = ALIASES.get(key, key)

    if key not in CODES:
        raise KeyError(
            "Model not found. Available models: "
            + ", ".join(sorted(CODES))
        )

    return CODES[key]

def models():
    """Show available model names."""
    return sorted(CODES)
